<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Edit RPH · {{ $school->name }}</title><style>:root{--ink:#172033;--muted:#687386;--blue:#2563eb;--line:#e5eaf2;--canvas:#f7f9fc}*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--ink);font:15px Arial,sans-serif}.top{height:72px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;background:#fff;border-bottom:1px solid var(--line)}.top a{color:var(--muted);text-decoration:none}.main{max-width:900px;margin:auto;padding:42px 24px 70px}.eyebrow{color:var(--blue);font-size:11px;font-weight:700;letter-spacing:.13em;text-transform:uppercase}.heading h1{margin:9px 0 8px;font-size:36px}.muted{color:var(--muted)}.notice{margin:20px 0;padding:12px 15px;border-radius:10px;background:#ecfdf5;color:#16704b}.card{margin-top:20px;padding:25px;border:1px solid var(--line);border-radius:16px;background:#fff}.grid{display:grid;grid-template-columns:repeat(2,1fr);gap:17px}label{display:block;color:#435067;font-size:12px;font-weight:700}input,select,textarea{display:block;width:100%;margin-top:7px;padding:11px 12px;border:1px solid #d9e0eb;border-radius:9px;background:#fff;font:14px Arial,sans-serif}textarea{min-height:100px;resize:vertical}.full{grid-column:1/-1}.button{margin-top:20px;border:0;border-radius:10px;min-height:44px;padding:0 17px;color:#fff;background:var(--blue);font-weight:700}@media(max-width:650px){.top{padding:0 18px}.main{padding:30px 16px}.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style></head>
<body><header class="top"><strong>✦ eRPH Pro</strong><a href="{{ route('workspace.dashboard') }}">Back to workspace</a></header><main class="main"><span class="eyebrow">{{ $school->subdomain }} / RPH version {{ $version->version }}</span><div class="heading"><h1>Edit lesson plan</h1><p class="muted">Saving creates a new version; previous versions remain available for review.</p></div>@if(session('status'))<div class="notice">{{ session('status') }}</div>@endif@php($content = $version->content)<form method="post" action="{{ route('rph.update', $lessonPlan) }}">@csrf @method('put')<section class="card"><div class="grid"><label>Date<input type="date" name="lesson_date" value="{{ old('lesson_date', $lessonPlan->lesson_date?->format('Y-m-d')) }}" required></label>@if($assignments->isNotEmpty())<label>Class and subject assignment<select name="assignment_id" required><option value="">Choose your assignment</option>@foreach($assignments as $assignment)<option value="{{ $assignment->id }}" @selected(old('assignment_id') == $assignment->id || ($assignment->subject === $lessonPlan->subject && $assignment->schoolClass->name === $lessonPlan->class_name))>{{ $assignment->subject }} · {{ $assignment->schoolClass->name }} · {{ $assignment->academicYear->year }}</option>@endforeach</select></label>@else<label>Subject<input name="subject" value="{{ old('subject', $lessonPlan->subject) }}" required></label><label>Class / year<input name="class_name" value="{{ old('class_name', $lessonPlan->class_name) }}" required></label>@endif<label>Lesson title<input name="title" value="{{ old('title', $content['title'] ?? '') }}" required></label><label class="full">Learning objectives<textarea name="objectives">{{ old('objectives', $content['objectives'] ?? '') }}</textarea></label><label class="full">Activities / steps<textarea name="activities">{{ old('activities', $content['activities'] ?? '') }}</textarea></label><label>Assessment<textarea name="assessment">{{ old('assessment', $content['assessment'] ?? '') }}</textarea></label><label>Reflection<textarea name="reflection">{{ old('reflection', $content['reflection'] ?? '') }}</textarea></label><label>Homework<textarea name="homework">{{ old('homework', $content['homework'] ?? '') }}</textarea></label><label>Materials / resources<textarea name="materials">{{ old('materials', $content['materials'] ?? '') }}</textarea></label><label class="full">Change note<textarea name="change_note" placeholder="What changed in this version?"></textarea></label></div><button class="button" type="submit">Save new version</button></section></form></main></body></html>
